/* ============================================================
   GLOBAL AID ALLIANCE — Main Stylesheet
   Design system: Professional + Warm Humanitarian
   Palette: Deep Red #C41E3A | Navy #1B3A5C | White | Warm Gray
   ============================================================ */

/* ── CSS Custom Properties ─────────────────────────────────── */
:root {
  /* Brand */
  --red:         #C41E3A;
  --red-dark:    #9E1830;
  --red-light:   #E8253F;
  --red-muted:   rgba(196,30,58,.08);
  --navy:        #1B3A5C;
  --navy-dark:   #112540;
  --navy-light:  #2A537E;

  /* Neutral */
  --white:       #FFFFFF;
  --gray-50:     #F8F9FA;
  --gray-100:    #F1F3F5;
  --gray-200:    #E9ECEF;
  --gray-300:    #DEE2E6;
  --gray-400:    #CED4DA;
  --gray-500:    #ADB5BD;
  --gray-600:    #6C757D;
  --gray-700:    #495057;
  --gray-800:    #343A40;
  --gray-900:    #212529;

  /* Semantic */
  --text-primary:   #1A1A2E;
  --text-secondary: #495057;
  --text-muted:     #6C757D;
  --border:         #DEE2E6;
  --surface:        #F8F9FA;

  /* Spacing (4pt scale) */
  --space-1:  4px;
  --space-2:  8px;
  --space-3:  12px;
  --space-4:  16px;
  --space-5:  20px;
  --space-6:  24px;
  --space-8:  32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;
  --space-20: 80px;
  --space-24: 96px;

  /* Typography */
  --font-heading: 'Merriweather', Georgia, serif;
  --font-body:    'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  /* Effects */
  --shadow-sm:  0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md:  0 4px 12px rgba(0,0,0,.10), 0 2px 4px rgba(0,0,0,.06);
  --shadow-lg:  0 10px 30px rgba(0,0,0,.12), 0 4px 8px rgba(0,0,0,.08);
  --shadow-xl:  0 20px 60px rgba(0,0,0,.15);

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  --transition: 200ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* ── Reset & Base ───────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.65;
  color: var(--text-primary);
  background: var(--white);
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul { list-style: none; }

button {
  font-family: var(--font-body);
  cursor: pointer;
  border: none;
  background: none;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ── Accessibility ──────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100px;
  left: var(--space-4);
  background: var(--red);
  color: var(--white);
  padding: var(--space-2) var(--space-4);
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  font-weight: 600;
  font-size: .9rem;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; outline: 3px solid var(--navy); outline-offset: 2px; }

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border-width: 0;
}

/* Focus ring – universal */
:focus-visible {
  outline: 3px solid var(--red);
  outline-offset: 3px;
  border-radius: 2px;
}

/* ── Layout Utilities ───────────────────────────────────────── */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding-inline: var(--space-5);
}

@media (min-width: 768px) {
  .container { padding-inline: var(--space-8); }
}

/* ── Shared Section Styles ──────────────────────────────────── */
.section-eyebrow {
  display: inline-block;
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: var(--space-2);
}
.section-eyebrow-light { color: rgba(255,255,255,.75); }

.section-heading-center {
  font-family: var(--font-heading);
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  font-weight: 900;
  line-height: 1.25;
  color: var(--text-primary);
  text-align: center;
  margin-bottom: var(--space-3);
}
.section-heading-light { color: var(--white); }

.section-subheading {
  text-align: center;
  color: var(--text-secondary);
  max-width: 640px;
  margin: 0 auto var(--space-12);
  font-size: 1.05rem;
}
.section-subheading-light { color: rgba(255,255,255,.8); }

/* ── Buttons ────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: 12px 24px;
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: .95rem;
  line-height: 1.2;
  transition: background var(--transition), color var(--transition),
              transform var(--transition), box-shadow var(--transition),
              border-color var(--transition);
  cursor: pointer;
  min-height: 44px;
  min-width: 44px;
  justify-content: center;
  white-space: nowrap;
}
.btn:active { transform: translateY(1px); }

.btn-donate {
  background: var(--red);
  color: var(--white);
  padding: 10px 22px;
  border-radius: var(--radius-md);
}
.btn-donate:hover { background: var(--red-dark); box-shadow: var(--shadow-sm); }

.btn-hero-primary {
  background: var(--red);
  color: var(--white);
  padding: 15px 32px;
  font-size: 1.05rem;
  border-radius: var(--radius-md);
  box-shadow: 0 4px 16px rgba(196,30,58,.4);
}
.btn-hero-primary:hover {
  background: var(--red-dark);
  box-shadow: 0 6px 20px rgba(196,30,58,.5);
  transform: translateY(-1px);
}

.btn-hero-secondary {
  background: rgba(255,255,255,.12);
  color: var(--white);
  border: 2px solid rgba(255,255,255,.5);
  padding: 13px 28px;
  font-size: 1.05rem;
  border-radius: var(--radius-md);
  backdrop-filter: blur(4px);
}
.btn-hero-secondary:hover {
  background: rgba(255,255,255,.22);
  border-color: var(--white);
}

.btn-outline-red {
  background: transparent;
  color: var(--red);
  border: 2px solid var(--red);
  border-radius: var(--radius-md);
  padding: 11px 22px;
}
.btn-outline-red:hover {
  background: var(--red);
  color: var(--white);
}

.btn-white {
  background: var(--white);
  color: var(--red);
  font-weight: 700;
  border-radius: var(--radius-md);
  padding: 12px 24px;
  box-shadow: var(--shadow-sm);
}
.btn-white:hover {
  background: var(--gray-100);
  box-shadow: var(--shadow-md);
}

.btn-red-outline-white {
  background: transparent;
  color: var(--white);
  border: 2px solid rgba(255,255,255,.6);
  border-radius: var(--radius-md);
  padding: 10px 22px;
  font-weight: 600;
  white-space: nowrap;
  flex-shrink: 0;
}
.btn-red-outline-white:hover {
  background: rgba(255,255,255,.12);
  border-color: var(--white);
}

.btn-donate-full {
  width: 100%;
  background: var(--red);
  color: var(--white);
  padding: 15px 24px;
  font-size: 1.05rem;
  font-weight: 700;
  border-radius: var(--radius-md);
  box-shadow: 0 4px 16px rgba(196,30,58,.35);
  justify-content: center;
}
.btn-donate-full:hover {
  background: var(--red-dark);
  box-shadow: 0 6px 20px rgba(196,30,58,.5);
  transform: translateY(-1px);
}

/* ── Header ─────────────────────────────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  box-shadow: 0 1px 0 var(--border), var(--shadow-sm);
}

.header-top {
  background: var(--navy);
  padding: 6px 0;
}
.header-top-inner {
  display: flex;
  justify-content: flex-end;
}
.utility-links {
  display: flex;
  gap: var(--space-5);
}
.utility-links a {
  color: rgba(255,255,255,.8);
  font-size: .8rem;
  transition: color var(--transition);
}
.utility-links a:hover { color: var(--white); }

.header-main { padding: 12px 0; }
.header-main-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  flex-shrink: 0;
}
.logo-icon { flex-shrink: 0; }
.logo-text {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}
.logo-name {
  font-family: var(--font-heading);
  font-weight: 900;
  font-size: 1rem;
  color: var(--navy);
}
.logo-tagline {
  font-size: .72rem;
  font-weight: 500;
  color: var(--text-muted);
  letter-spacing: .03em;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}
.main-nav ul {
  display: flex;
  align-items: center;
  gap: 4px;
}
.main-nav ul a {
  display: block;
  padding: 8px 12px;
  font-size: .88rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.main-nav ul a:hover { color: var(--navy); background: var(--gray-100); }

.hamburger {
  display: none;
  align-items: center;
  justify-content: center;
  width: 44px; height: 44px;
  color: var(--text-primary);
  border-radius: var(--radius-md);
  transition: background var(--transition);
}
.hamburger:hover { background: var(--gray-100); }

/* Mobile nav */
.mobile-nav-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.5);
  z-index: 199;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition-slow);
}
.mobile-nav-overlay.active {
  opacity: 1;
  pointer-events: all;
}

.mobile-nav {
  position: fixed;
  top: 0; right: 0;
  width: min(320px, 85vw);
  height: 100dvh;
  background: var(--white);
  z-index: 200;
  padding: var(--space-6);
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  transform: translateX(100%);
  transition: transform var(--transition-slow);
  box-shadow: var(--shadow-xl);
  overflow-y: auto;
}
.mobile-nav.open {
  transform: translateX(0);
}

.mobile-nav-close {
  align-self: flex-end;
  width: 44px; height: 44px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-md);
  color: var(--text-primary);
  transition: background var(--transition);
}
.mobile-nav-close:hover { background: var(--gray-100); }

.mobile-nav ul {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.mobile-nav-link {
  display: block;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-primary);
  border-radius: var(--radius-md);
  transition: background var(--transition), color var(--transition);
}
.mobile-nav-link:hover { background: var(--gray-100); color: var(--navy); }

.btn-donate-mobile {
  margin-top: auto;
}

/* ── Hero ───────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 600px;
  display: flex;
  align-items: center;
  overflow: hidden;
}

@media (min-width: 768px) { .hero { min-height: 700px; } }
@media (min-width: 1200px) { .hero { min-height: 780px; } }

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.hero-bg-image {
  position: absolute;
  inset: 0;
}
.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    rgba(17,37,64,.92) 0%,
    rgba(27,58,92,.80) 50%,
    rgba(27,58,92,.55) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 1;
  padding-block: var(--space-20);
  max-width: 680px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.25);
  color: rgba(255,255,255,.9);
  font-size: .8rem;
  font-weight: 600;
  letter-spacing: .04em;
  padding: 6px 14px;
  border-radius: 99px;
  margin-bottom: var(--space-5);
  backdrop-filter: blur(4px);
}

.hero-content h1 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3.4rem);
  font-weight: 900;
  line-height: 1.15;
  color: var(--white);
  margin-bottom: var(--space-5);
  text-shadow: 0 2px 12px rgba(0,0,0,.3);
}

.hero-subtitle {
  font-size: clamp(1rem, 1.6vw, 1.15rem);
  color: rgba(255,255,255,.88);
  line-height: 1.7;
  margin-bottom: var(--space-8);
  max-width: 560px;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  margin-bottom: var(--space-8);
}

.hero-trust {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-5);
}
.hero-trust span {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  color: rgba(255,255,255,.7);
  font-size: .82rem;
}

/* ── Impact Stats ───────────────────────────────────────────── */
.impact-stats {
  padding-block: var(--space-20);
  background: var(--white);
}

.impact-stats .section-heading-center {
  margin-bottom: var(--space-12);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-5);
  counter-reset: stats;
}

@media (min-width: 768px) {
  .stats-grid { grid-template-columns: repeat(4, 1fr); }
}

.stat-card {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-8) var(--space-6);
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
  overflow: hidden;
}
.stat-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px;
  background: var(--red);
  border-radius: var(--radius-xl) var(--radius-xl) 0 0;
}
.stat-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.stat-number {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 2.8rem);
  font-weight: 900;
  color: var(--red);
  line-height: 1;
  margin-bottom: var(--space-2);
  font-variant-numeric: tabular-nums;
}

.stat-label {
  font-size: .95rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: var(--space-2);
}

.stat-desc {
  font-size: .82rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* ── Mission ────────────────────────────────────────────────── */
.mission {
  padding-block: var(--space-24);
  background: var(--gray-50);
}

.mission-inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-12);
  align-items: center;
}

@media (min-width: 900px) {
  .mission-inner { grid-template-columns: 1fr 1fr; }
}

.mission-image {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}
.mission-image img {
  width: 100%;
  height: 400px;
  object-fit: cover;
}
.mission-image-badge {
  position: absolute;
  bottom: var(--space-4);
  left: var(--space-4);
  background: var(--white);
  border-radius: var(--radius-md);
  padding: var(--space-2) var(--space-4);
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: .85rem;
  font-weight: 600;
  color: var(--navy);
  box-shadow: var(--shadow-md);
}

.mission-content h2 {
  font-family: var(--font-heading);
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  font-weight: 900;
  color: var(--navy);
  line-height: 1.25;
  margin-bottom: var(--space-5);
}

.mission-statement {
  background: var(--red-muted);
  border-left: 4px solid var(--red);
  padding: var(--space-4) var(--space-5);
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  margin-bottom: var(--space-5);
  color: var(--text-primary);
  font-size: 1.02rem;
  line-height: 1.7;
}

.mission-content p {
  color: var(--text-secondary);
  line-height: 1.75;
  margin-bottom: var(--space-4);
}

.mission-principles {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-top: var(--space-6);
}

.principle {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  background: var(--white);
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
}
.principle-icon {
  width: 36px; height: 36px;
  background: var(--red-muted);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.principle > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.principle strong {
  font-size: .9rem;
  color: var(--navy);
}
.principle span {
  font-size: .82rem;
  color: var(--text-muted);
}

/* ── Programs (Accordion) ───────────────────────────────────── */
.programs {
  padding-block: var(--space-24);
  background: var(--white);
}
.programs .section-eyebrow,
.programs .section-heading-center { text-align: center; }

.accordion {
  max-width: 760px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.accordion-item {
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--white);
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition);
}
.accordion-item:has(.accordion-trigger[aria-expanded="true"]) {
  box-shadow: var(--shadow-md);
  border-color: var(--red);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  gap: var(--space-4);
  padding: var(--space-5) var(--space-6);
  text-align: left;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--white);
  transition: background var(--transition), color var(--transition);
}
.accordion-trigger:hover { background: var(--gray-50); color: var(--navy); }
.accordion-trigger[aria-expanded="true"] {
  color: var(--red);
  background: rgba(196,30,58,.04);
}

.accordion-icon {
  width: 36px; height: 36px;
  background: var(--gray-100);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  color: var(--red);
  transition: background var(--transition);
}
.accordion-trigger[aria-expanded="true"] .accordion-icon {
  background: var(--red-muted);
}

.accordion-trigger span {
  flex: 1;
}

.accordion-chevron {
  flex-shrink: 0;
  color: var(--text-muted);
  transition: transform var(--transition-slow), color var(--transition);
}
.accordion-trigger[aria-expanded="true"] .accordion-chevron {
  transform: rotate(180deg);
  color: var(--red);
}

.accordion-panel {
  overflow: hidden;
  max-height: 0;
  transition: max-height var(--transition-slow) ease;
}
.accordion-panel:not([hidden]) {
  max-height: 300px;
}
.accordion-panel[hidden] {
  display: block !important;
  max-height: 0;
  visibility: hidden;
}

.accordion-content {
  padding: 0 var(--space-6) var(--space-6) calc(36px + var(--space-6) + var(--space-4));
  color: var(--text-secondary);
  line-height: 1.75;
  font-size: .95rem;
}

.accordion-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  margin-top: var(--space-3);
  color: var(--red);
  font-weight: 600;
  font-size: .9rem;
  transition: gap var(--transition), opacity var(--transition);
}
.accordion-link:hover { gap: var(--space-2); opacity: .8; }

/* ── Get Involved ───────────────────────────────────────────── */
.get-involved {
  padding-block: var(--space-24);
  background: var(--navy);
}

.involved-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-6);
  margin-bottom: var(--space-6);
}
@media (min-width: 768px) {
  .involved-grid { grid-template-columns: repeat(3, 1fr); }
}

.involved-card {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  transition: background var(--transition), transform var(--transition);
}
.involved-card:hover {
  background: rgba(255,255,255,.1);
  transform: translateY(-4px);
}
.involved-card-featured {
  background: var(--red);
  border-color: var(--red-light);
  position: relative;
}
.involved-card-featured:hover {
  background: var(--red-dark);
}

.featured-badge {
  display: inline-block;
  background: rgba(255,255,255,.2);
  color: var(--white);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: 99px;
  margin-bottom: var(--space-3);
}

.involved-card-icon {
  width: 60px; height: 60px;
  background: rgba(255,255,255,.1);
  border-radius: var(--radius-lg);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: var(--space-5);
}

.involved-card h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: var(--space-3);
}
.involved-card p {
  color: rgba(255,255,255,.75);
  font-size: .92rem;
  line-height: 1.7;
  margin-bottom: var(--space-5);
}

.blood-drive-cta {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: var(--radius-xl);
  padding: var(--space-6) var(--space-8);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  flex-wrap: wrap;
}
.blood-drive-content {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  flex: 1;
}
.blood-drive-content div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.blood-drive-content strong {
  color: var(--white);
  font-size: 1rem;
}
.blood-drive-content span {
  color: rgba(255,255,255,.7);
  font-size: .88rem;
}

/* ── News Carousel ──────────────────────────────────────────── */
.news {
  padding-block: var(--space-24);
  background: var(--gray-50);
}

.news-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: var(--space-8);
  gap: var(--space-4);
  flex-wrap: wrap;
}
.news-header h2 {
  font-family: var(--font-heading);
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  font-weight: 900;
  color: var(--navy);
}

.carousel-controls {
  display: flex;
  gap: var(--space-2);
  flex-shrink: 0;
}
.carousel-btn {
  width: 44px; height: 44px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-secondary);
  background: var(--white);
  transition: background var(--transition), border-color var(--transition),
              color var(--transition), box-shadow var(--transition);
}
.carousel-btn:hover {
  background: var(--navy);
  border-color: var(--navy);
  color: var(--white);
  box-shadow: var(--shadow-sm);
}

.carousel-viewport {
  overflow: hidden;
  border-radius: var(--radius-xl);
}

.carousel-track {
  display: flex;
  gap: var(--space-5);
  transition: transform var(--transition-slow) cubic-bezier(0.4, 0, 0.2, 1);
}

.news-card {
  flex: 0 0 calc(100% - 0px);
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
  transition: box-shadow var(--transition);
}
.news-card:hover { box-shadow: var(--shadow-md); }

@media (min-width: 768px) {
  .news-card { flex: 0 0 calc(50% - 10px); }
}
@media (min-width: 1024px) {
  .news-card { flex: 0 0 calc(33.333% - 14px); }
}

.news-card-image {
  position: relative;
  overflow: hidden;
}
.news-card-image img {
  width: 100%;
  height: 200px;
  object-fit: cover;
  transition: transform 400ms ease;
}
.news-card:hover .news-card-image img { transform: scale(1.04); }

.news-tag {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 99px;
}
.news-tag-urgent  { background: #fee2e2; color: #991b1b; }
.news-tag-ongoing { background: #fef3c7; color: #92400e; }
.news-tag-campaign{ background: #dbeafe; color: #1e40af; }
.news-tag-story   { background: #d1fae5; color: #065f46; }

.news-card-content { padding: var(--space-5) var(--space-6); }

.news-date {
  display: block;
  font-size: .78rem;
  color: var(--text-muted);
  margin-bottom: var(--space-2);
  font-weight: 500;
}

.news-card-content h3 {
  font-size: 1rem;
  font-weight: 700;
  color: var(--navy);
  line-height: 1.4;
  margin-bottom: var(--space-3);
}
.news-card-content h3 a { transition: color var(--transition); }
.news-card-content h3 a:hover { color: var(--red); }

.news-card-content p {
  font-size: .88rem;
  color: var(--text-secondary);
  line-height: 1.65;
  margin-bottom: var(--space-4);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.news-read-more {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  color: var(--red);
  font-size: .85rem;
  font-weight: 600;
  transition: gap var(--transition);
}
.news-read-more:hover { gap: var(--space-2); }

.carousel-indicators {
  display: flex;
  justify-content: center;
  gap: var(--space-2);
  margin-top: var(--space-6);
}
.carousel-dot {
  width: 8px; height: 8px;
  border-radius: 99px;
  background: var(--gray-300);
  transition: background var(--transition), width var(--transition);
  cursor: pointer;
}
.carousel-dot.active {
  background: var(--red);
  width: 24px;
}

/* ── Donate CTA ─────────────────────────────────────────────── */
.donate-cta {
  padding-block: var(--space-24);
  background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 60%, var(--navy-light) 100%);
  position: relative;
  overflow: hidden;
}
.donate-cta::before {
  content: '';
  position: absolute;
  top: -60px; right: -60px;
  width: 300px; height: 300px;
  border-radius: 50%;
  background: rgba(196,30,58,.12);
  pointer-events: none;
}
.donate-cta::after {
  content: '';
  position: absolute;
  bottom: -80px; left: -40px;
  width: 250px; height: 250px;
  border-radius: 50%;
  background: rgba(255,255,255,.04);
  pointer-events: none;
}

.donate-cta-inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-12);
  align-items: start;
  position: relative;
  z-index: 1;
}
@media (min-width: 900px) {
  .donate-cta-inner { grid-template-columns: 1fr 1fr; align-items: center; }
}

.donate-cta-content h2 {
  font-family: var(--font-heading);
  font-size: clamp(1.7rem, 3vw, 2.4rem);
  font-weight: 900;
  color: var(--white);
  line-height: 1.2;
  margin-bottom: var(--space-5);
}

.donate-desc {
  color: rgba(255,255,255,.8);
  line-height: 1.75;
  margin-bottom: var(--space-6);
}
.donate-desc strong { color: var(--white); }

.donate-trust-badges {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4);
}
.trust-badge {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  color: rgba(255,255,255,.7);
  font-size: .82rem;
  font-weight: 500;
}

.donate-cta-form {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  box-shadow: var(--shadow-xl);
}
.donate-cta-form h3 {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: var(--space-5);
  text-align: center;
}

.amount-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-3);
  margin-bottom: var(--space-5);
}

.amount-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: var(--space-4) var(--space-3);
  border: 2px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--white);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition), transform var(--transition);
  position: relative;
  text-align: center;
}
.amount-btn:hover {
  border-color: var(--red);
  background: var(--red-muted);
  transform: translateY(-2px);
}
.amount-btn.selected {
  border-color: var(--red);
  background: var(--red-muted);
}
.amount-btn-popular {
  border-color: var(--red);
  background: var(--red-muted);
}

.popular-label {
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--red);
  color: var(--white);
  font-size: .65rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 99px;
  white-space: nowrap;
}

.amount-value {
  font-family: var(--font-heading);
  font-size: 1.4rem;
  font-weight: 900;
  color: var(--navy);
  line-height: 1.2;
}
.amount-impact {
  font-size: .75rem;
  color: var(--text-muted);
  margin-top: 2px;
}

/* ── Donate Modal ───────────────────────────────────────────── */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.6);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-4);
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition-slow);
  backdrop-filter: blur(4px);
}
.modal-overlay.open {
  opacity: 1;
  pointer-events: all;
}

.modal-container {
  background: var(--white);
  border-radius: var(--radius-xl);
  width: 100%;
  max-width: 540px;
  max-height: 90dvh;
  overflow-y: auto;
  position: relative;
  box-shadow: var(--shadow-xl);
  transform: scale(0.95) translateY(10px);
  transition: transform var(--transition-slow);
}
.modal-overlay.open .modal-container {
  transform: scale(1) translateY(0);
}

.modal-close {
  position: absolute;
  top: var(--space-4);
  right: var(--space-4);
  width: 44px; height: 44px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-md);
  color: var(--text-muted);
  transition: background var(--transition), color var(--transition);
  z-index: 1;
}
.modal-close:hover { background: var(--gray-100); color: var(--text-primary); }

.modal-header {
  background: linear-gradient(135deg, var(--navy-dark), var(--navy));
  padding: var(--space-8) var(--space-8) var(--space-6);
  text-align: center;
  border-radius: var(--radius-xl) var(--radius-xl) 0 0;
}
.modal-logo {
  margin: 0 auto var(--space-3);
  width: fit-content;
}
.modal-header h2 {
  font-family: var(--font-heading);
  font-size: 1.4rem;
  font-weight: 900;
  color: var(--white);
  margin-bottom: var(--space-2);
}
.modal-header p {
  color: rgba(255,255,255,.75);
  font-size: .9rem;
}

.modal-form {
  padding: var(--space-6) var(--space-8) var(--space-8);
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
}

.form-legend {
  font-size: .82rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: var(--space-3);
  display: block;
}

fieldset { border: none; }

.modal-amounts {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-3);
}

.modal-amount-label { cursor: pointer; }
.modal-amount-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: var(--space-4) var(--space-3);
  border: 2px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--white);
  transition: border-color var(--transition), background var(--transition);
  position: relative;
  text-align: center;
}
input[type="radio"]:checked + .modal-amount-btn,
.modal-amount-btn-selected {
  border-color: var(--red) !important;
  background: var(--red-muted) !important;
}
.modal-amount-label:hover .modal-amount-btn {
  border-color: var(--red);
  background: var(--red-muted);
}
.modal-popular-tag {
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--red);
  color: var(--white);
  font-size: .65rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 99px;
  white-space: nowrap;
}
.modal-amount-value {
  font-family: var(--font-heading);
  font-size: 1.3rem;
  font-weight: 900;
  color: var(--navy);
  line-height: 1.2;
}
.modal-amount-impact {
  font-size: .72rem;
  color: var(--text-muted);
  margin-top: 2px;
}

.custom-amount-row {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  margin-top: var(--space-3);
}
.custom-amount-label {
  font-size: .88rem;
  font-weight: 500;
  color: var(--text-secondary);
}
.custom-amount-input-wrap {
  position: relative;
}
.currency-prefix {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  font-weight: 600;
  color: var(--text-secondary);
  pointer-events: none;
}
.custom-amount-input {
  width: 100%;
  padding: 10px 12px 10px 28px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  font-family: var(--font-body);
  font-size: .95rem;
  color: var(--text-primary);
  background: var(--white);
  transition: border-color var(--transition), box-shadow var(--transition);
}
.custom-amount-input:focus {
  border-color: var(--red);
  outline: none;
  box-shadow: 0 0 0 3px rgba(196,30,58,.15);
}
.form-hint {
  font-size: .78rem;
  color: var(--text-muted);
}

.freq-row {
  display: flex;
  gap: var(--space-3);
}
.freq-label {
  flex: 1;
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: 10px var(--space-4);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  font-size: .9rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
}
.freq-label:has(input:checked) {
  border-color: var(--navy);
  background: rgba(27,58,92,.06);
  color: var(--navy);
}
.freq-label input { accent-color: var(--navy); }

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-4);
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}
.form-label {
  font-size: .88rem;
  font-weight: 600;
  color: var(--text-secondary);
}
.required { color: var(--red); }
.form-input {
  padding: 10px 12px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  font-family: var(--font-body);
  font-size: .95rem;
  color: var(--text-primary);
  background: var(--white);
  transition: border-color var(--transition), box-shadow var(--transition);
  min-height: 44px;
}
.form-input:focus {
  border-color: var(--red);
  outline: none;
  box-shadow: 0 0 0 3px rgba(196,30,58,.15);
}

.modal-actions {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}
.modal-security {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  font-size: .78rem;
  color: var(--text-muted);
  text-align: center;
}

/* ── Footer ─────────────────────────────────────────────────── */
.site-footer {
  background: var(--gray-900);
  color: rgba(255,255,255,.7);
}

.footer-top {
  padding: var(--space-16) 0 var(--space-12);
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-12);
}
@media (min-width: 900px) {
  .footer-top { grid-template-columns: 280px 1fr; }
}

.footer-brand .logo-name { color: var(--white); }
.footer-brand .logo-tagline { color: rgba(255,255,255,.5); }

.footer-desc {
  font-size: .9rem;
  line-height: 1.7;
  color: rgba(255,255,255,.6);
  margin-top: var(--space-4);
  margin-bottom: var(--space-5);
}

.footer-social {
  display: flex;
  gap: var(--space-3);
}
.footer-social a {
  width: 38px; height: 38px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,.6);
  transition: background var(--transition), color var(--transition), border-color var(--transition);
}
.footer-social a:hover {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.footer-nav {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-8);
}
@media (min-width: 600px) {
  .footer-nav { grid-template-columns: repeat(4, 1fr); }
}

.footer-nav-col h4 {
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--white);
  margin-bottom: var(--space-4);
}
.footer-nav-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}
.footer-nav-col a {
  font-size: .88rem;
  color: rgba(255,255,255,.55);
  transition: color var(--transition);
  line-height: 1.4;
}
.footer-nav-col a:hover { color: var(--white); }

.footer-bottom {
  padding-block: var(--space-5);
  border-top: 1px solid rgba(255,255,255,.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  flex-wrap: wrap;
  font-size: .82rem;
  color: rgba(255,255,255,.4);
}
.footer-bottom-links {
  display: flex;
  gap: var(--space-4);
}
.footer-bottom-links a {
  color: rgba(255,255,255,.4);
  transition: color var(--transition);
}
.footer-bottom-links a:hover { color: rgba(255,255,255,.7); }

/* ── Responsive Adjustments ─────────────────────────────────── */
@media (max-width: 767px) {
  .main-nav { display: none; }
  .hamburger { display: flex; }

  .hero-actions .btn { width: 100%; justify-content: center; }
  .hero-actions { flex-direction: column; }

  .stats-grid { grid-template-columns: repeat(2,1fr); gap: var(--space-4); }

  .mission-image img { height: 260px; }

  .accordion-content { padding-left: var(--space-6); }

  .donate-cta-inner { gap: var(--space-8); }

  .form-row { grid-template-columns: 1fr; }

  .modal-form { padding: var(--space-5) var(--space-5) var(--space-6); }
  .modal-header { padding: var(--space-6) var(--space-5) var(--space-5); }
}

@media (max-width: 480px) {
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .stat-card { padding: var(--space-5) var(--space-4); }
  .blood-drive-cta { flex-direction: column; align-items: flex-start; }
  .utility-links { display: none; }
}

/* ── Animations ─────────────────────────────────────────────── */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes countUp {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.stat-card { animation: fadeInUp 0.4s ease both; }
.stat-card:nth-child(1) { animation-delay: 0.05s; }
.stat-card:nth-child(2) { animation-delay: 0.12s; }
.stat-card:nth-child(3) { animation-delay: 0.19s; }
.stat-card:nth-child(4) { animation-delay: 0.26s; }

/* ============================================================
   GLOBAL AID ALLIANCE — Main Stylesheet
   Design system: Professional + Warm Humanitarian
   Palette: Deep Red #C41E3A | Navy #1B3A5C | White | Warm Gray
   ============================================================ */

/* ── CSS Custom Properties ─────────────────────────────────── */
:root {
  /* Brand */
  --red:         #C41E3A;
  --red-dark:    #9E1830;
  --red-light:   #E8253F;
  --red-muted:   rgba(196,30,58,.08);
  --navy:        #1B3A5C;
  --navy-dark:   #112540;
  --navy-light:  #2A537E;

  /* Neutral */
  --white:       #FFFFFF;
  --gray-50:     #F8F9FA;
  --gray-100:    #F1F3F5;
  --gray-200:    #E9ECEF;
  --gray-300:    #DEE2E6;
  --gray-400:    #CED4DA;
  --gray-500:    #ADB5BD;
  --gray-600:    #6C757D;
  --gray-700:    #495057;
  --gray-800:    #343A40;
  --gray-900:    #212529;

  /* Semantic */
  --text-primary:   #1A1A2E;
  --text-secondary: #495057;
  --text-muted:     #6C757D;
  --border:         #DEE2E6;
  --surface:        #F8F9FA;

  /* Spacing (4pt scale) */
  --space-1:  4px;
  --space-2:  8px;
  --space-3:  12px;
  --space-4:  16px;
  --space-5:  20px;
  --space-6:  24px;
  --space-8:  32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;
  --space-20: 80px;
  --space-24: 96px;

  /* Typography */
  --font-heading: 'Merriweather', Georgia, serif;
  --font-body:    'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  /* Effects */
  --shadow-sm:  0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md:  0 4px 12px rgba(0,0,0,.10), 0 2px 4px rgba(0,0,0,.06);
  --shadow-lg:  0 10px 30px rgba(0,0,0,.12), 0 4px 8px rgba(0,0,0,.08);
  --shadow-xl:  0 20px 60px rgba(0,0,0,.15);

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  --transition: 200ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* ── Reset & Base ───────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.65;
  color: var(--text-primary);
  background: var(--white);
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul { list-style: none; }

button {
  font-family: var(--font-body);
  cursor: pointer;
  border: none;
  background: none;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ── Accessibility ──────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100px;
  left: var(--space-4);
  background: var(--red);
  color: var(--white);
  padding: var(--space-2) var(--space-4);
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  font-weight: 600;
  font-size: .9rem;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; outline: 3px solid var(--navy); outline-offset: 2px; }

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border-width: 0;
}

/* Focus ring – universal */
:focus-visible {
  outline: 3px solid var(--red);
  outline-offset: 3px;
  border-radius: 2px;
}

/* ── Layout Utilities ───────────────────────────────────────── */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding-inline: var(--space-5);
}

@media (min-width: 768px) {
  .container { padding-inline: var(--space-8); }
}

/* ── Shared Section Styles ──────────────────────────────────── */
.section-eyebrow {
  display: inline-block;
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: var(--space-2);
}
.section-eyebrow-light { color: rgba(255,255,255,.75); }

.section-heading-center {
  font-family: var(--font-heading);
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  font-weight: 900;
  line-height: 1.25;
  color: var(--text-primary);
  text-align: center;
  margin-bottom: var(--space-3);
}
.section-heading-light { color: var(--white); }

.section-subheading {
  text-align: center;
  color: var(--text-secondary);
  max-width: 640px;
  margin: 0 auto var(--space-12);
  font-size: 1.05rem;
}
.section-subheading-light { color: rgba(255,255,255,.8); }

/* ── Buttons ────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: 12px 24px;
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: .95rem;
  line-height: 1.2;
  transition: background var(--transition), color var(--transition),
              transform var(--transition), box-shadow var(--transition),
              border-color var(--transition);
  cursor: pointer;
  min-height: 44px;
  min-width: 44px;
  justify-content: center;
  white-space: nowrap;
}
.btn:active { transform: translateY(1px); }

.btn-donate {
  background: var(--red);
  color: var(--white);
  padding: 10px 22px;
  border-radius: var(--radius-md);
}
.btn-donate:hover { background: var(--red-dark); box-shadow: var(--shadow-sm); }

.btn-hero-primary {
  background: var(--red);
  color: var(--white);
  padding: 15px 32px;
  font-size: 1.05rem;
  border-radius: var(--radius-md);
  box-shadow: 0 4px 16px rgba(196,30,58,.4);
}
.btn-hero-primary:hover {
  background: var(--red-dark);
  box-shadow: 0 6px 20px rgba(196,30,58,.5);
  transform: translateY(-1px);
}

.btn-hero-secondary {
  background: rgba(255,255,255,.12);
  color: var(--white);
  border: 2px solid rgba(255,255,255,.5);
  padding: 13px 28px;
  font-size: 1.05rem;
  border-radius: var(--radius-md);
  backdrop-filter: blur(4px);
}
.btn-hero-secondary:hover {
  background: rgba(255,255,255,.22);
  border-color: var(--white);
}

.btn-outline-red {
  background: transparent;
  color: var(--red);
  border: 2px solid var(--red);
  border-radius: var(--radius-md);
  padding: 11px 22px;
}
.btn-outline-red:hover {
  background: var(--red);
  color: var(--white);
}

.btn-white {
  background: var(--white);
  color: var(--red);
  font-weight: 700;
  border-radius: var(--radius-md);
  padding: 12px 24px;
  box-shadow: var(--shadow-sm);
}
.btn-white:hover {
  background: var(--gray-100);
  box-shadow: var(--shadow-md);
}

.btn-red-outline-white {
  background: transparent;
  color: var(--white);
  border: 2px solid rgba(255,255,255,.6);
  border-radius: var(--radius-md);
  padding: 10px 22px;
  font-weight: 600;
  white-space: nowrap;
  flex-shrink: 0;
}
.btn-red-outline-white:hover {
  background: rgba(255,255,255,.12);
  border-color: var(--white);
}

.btn-donate-full {
  width: 100%;
  background: var(--red);
  color: var(--white);
  padding: 15px 24px;
  font-size: 1.05rem;
  font-weight: 700;
  border-radius: var(--radius-md);
  box-shadow: 0 4px 16px rgba(196,30,58,.35);
  justify-content: center;
}
.btn-donate-full:hover {
  background: var(--red-dark);
  box-shadow: 0 6px 20px rgba(196,30,58,.5);
  transform: translateY(-1px);
}

/* ── Header ─────────────────────────────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  box-shadow: 0 1px 0 var(--border), var(--shadow-sm);
}

.header-top {
  background: var(--navy);
  padding: 6px 0;
}
.header-top-inner {
  display: flex;
  justify-content: flex-end;
}
.utility-links {
  display: flex;
  gap: var(--space-5);
}
.utility-links a {
  color: rgba(255,255,255,.8);
  font-size: .8rem;
  transition: color var(--transition);
}
.utility-links a:hover { color: var(--white); }

.header-main { padding: 12px 0; }
.header-main-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  flex-shrink: 0;
}
.logo-icon { flex-shrink: 0; }
.logo-text {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}
.logo-name {
  font-family: var(--font-heading);
  font-weight: 900;
  font-size: 1rem;
  color: var(--navy);
}
.logo-tagline {
  font-size: .72rem;
  font-weight: 500;
  color: var(--text-muted);
  letter-spacing: .03em;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}
.main-nav ul {
  display: flex;
  align-items: center;
  gap: 4px;
}
.main-nav ul a {
  display: block;
  padding: 8px 12px;
  font-size: .88rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.main-nav ul a:hover { color: var(--navy); background: var(--gray-100); }

.hamburger {
  display: none;
  align-items: center;
  justify-content: center;
  width: 44px; height: 44px;
  color: var(--text-primary);
  border-radius: var(--radius-md);
  transition: background var(--transition);
}
.hamburger:hover { background: var(--gray-100); }

/* Mobile nav */
.mobile-nav-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.5);
  z-index: 199;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition-slow);
}
.mobile-nav-overlay.active {
  opacity: 1;
  pointer-events: all;
}

.mobile-nav {
  position: fixed;
  top: 0; right: 0;
  width: min(320px, 85vw);
  height: 100dvh;
  background: var(--white);
  z-index: 200;
  padding: var(--space-6);
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  transform: translateX(100%);
  transition: transform var(--transition-slow);
  box-shadow: var(--shadow-xl);
  overflow-y: auto;
}
.mobile-nav.open {
  transform: translateX(0);
}

.mobile-nav-close {
  align-self: flex-end;
  width: 44px; height: 44px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-md);
  color: var(--text-primary);
  transition: background var(--transition);
}
.mobile-nav-close:hover { background: var(--gray-100); }

.mobile-nav ul {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.mobile-nav-link {
  display: block;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-primary);
  border-radius: var(--radius-md);
  transition: background var(--transition), color var(--transition);
}
.mobile-nav-link:hover { background: var(--gray-100); color: var(--navy); }

.btn-donate-mobile {
  margin-top: auto;
}

/* ── Hero ───────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 600px;
  display: flex;
  align-items: center;
  overflow: hidden;
}

@media (min-width: 768px) { .hero { min-height: 700px; } }
@media (min-width: 1200px) { .hero { min-height: 780px; } }

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.hero-bg-image {
  position: absolute;
  inset: 0;
}
.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    rgba(17,37,64,.92) 0%,
    rgba(27,58,92,.80) 50%,
    rgba(27,58,92,.55) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 1;
  padding-block: var(--space-20);
  max-width: 680px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.25);
  color: rgba(255,255,255,.9);
  font-size: .8rem;
  font-weight: 600;
  letter-spacing: .04em;
  padding: 6px 14px;
  border-radius: 99px;
  margin-bottom: var(--space-5);
  backdrop-filter: blur(4px);
}

.hero-content h1 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3.4rem);
  font-weight: 900;
  line-height: 1.15;
  color: var(--white);
  margin-bottom: var(--space-5);
  text-shadow: 0 2px 12px rgba(0,0,0,.3);
}

.hero-subtitle {
  font-size: clamp(1rem, 1.6vw, 1.15rem);
  color: rgba(255,255,255,.88);
  line-height: 1.7;
  margin-bottom: var(--space-8);
  max-width: 560px;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  margin-bottom: var(--space-8);
}

.hero-trust {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-5);
}
.hero-trust span {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  color: rgba(255,255,255,.7);
  font-size: .82rem;
}

/* ── Impact Stats ───────────────────────────────────────────── */
.impact-stats {
  padding-block: var(--space-20);
  background: var(--white);
}

.impact-stats .section-heading-center {
  margin-bottom: var(--space-12);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-5);
  counter-reset: stats;
}

@media (min-width: 768px) {
  .stats-grid { grid-template-columns: repeat(4, 1fr); }
}

.stat-card {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: var(--space-8) var(--space-6);
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
  overflow: hidden;
}
.stat-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px;
  background: var(--red);
  border-radius: var(--radius-xl) var(--radius-xl) 0 0;
}
.stat-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.stat-number {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 2.8rem);
  font-weight: 900;
  color: var(--red);
  line-height: 1;
  margin-bottom: var(--space-2);
  font-variant-numeric: tabular-nums;
}

.stat-label {
  font-size: .95rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: var(--space-2);
}

.stat-desc {
  font-size: .82rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* ── Mission ────────────────────────────────────────────────── */
.mission {
  padding-block: var(--space-24);
  background: var(--gray-50);
}

.mission-inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-12);
  align-items: center;
}

@media (min-width: 900px) {
  .mission-inner { grid-template-columns: 1fr 1fr; }
}

.mission-image {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}
.mission-image img {
  width: 100%;
  height: 400px;
  object-fit: cover;
}
.mission-image-badge {
  position: absolute;
  bottom: var(--space-4);
  left: var(--space-4);
  background: var(--white);
  border-radius: var(--radius-md);
  padding: var(--space-2) var(--space-4);
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: .85rem;
  font-weight: 600;
  color: var(--navy);
  box-shadow: var(--shadow-md);
}

.mission-content h2 {
  font-family: var(--font-heading);
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  font-weight: 900;
  color: var(--navy);
  line-height: 1.25;
  margin-bottom: var(--space-5);
}

.mission-statement {
  background: var(--red-muted);
  border-left: 4px solid var(--red);
  padding: var(--space-4) var(--space-5);
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  margin-bottom: var(--space-5);
  color: var(--text-primary);
  font-size: 1.02rem;
  line-height: 1.7;
}

.mission-content p {
  color: var(--text-secondary);
  line-height: 1.75;
  margin-bottom: var(--space-4);
}

.mission-principles {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-top: var(--space-6);
}

.principle {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  background: var(--white);
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
}
.principle-icon {
  width: 36px; height: 36px;
  background: var(--red-muted);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.principle > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.principle strong {
  font-size: .9rem;
  color: var(--navy);
}
.principle span {
  font-size: .82rem;
  color: var(--text-muted);
}

/* ── Programs (Accordion) ───────────────────────────────────── */
.programs {
  padding-block: var(--space-24);
  background: var(--white);
}
.programs .section-eyebrow,
.programs .section-heading-center { text-align: center; }

.accordion {
  max-width: 760px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.accordion-item {
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--white);
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition);
}
.accordion-item:has(.accordion-trigger[aria-expanded="true"]) {
  box-shadow: var(--shadow-md);
  border-color: var(--red);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  gap: var(--space-4);
  padding: var(--space-5) var(--space-6);
  text-align: left;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--white);
  transition: background var(--transition), color var(--transition);
}
.accordion-trigger:hover { background: var(--gray-50); color: var(--navy); }
.accordion-trigger[aria-expanded="true"] {
  color: var(--red);
  background: rgba(196,30,58,.04);
}

.accordion-icon {
  width: 36px; height: 36px;
  background: var(--gray-100);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  color: var(--red);
  transition: background var(--transition);
}
.accordion-trigger[aria-expanded="true"] .accordion-icon {
  background: var(--red-muted);
}

.accordion-trigger span {
  flex: 1;
}

.accordion-chevron {
  flex-shrink: 0;
  color: var(--text-muted);
  transition: transform var(--transition-slow), color var(--transition);
}
.accordion-trigger[aria-expanded="true"] .accordion-chevron {
  transform: rotate(180deg);
  color: var(--red);
}

.accordion-panel {
  overflow: hidden;
  max-height: 0;
  transition: max-height var(--transition-slow) ease;
}
.accordion-panel:not([hidden]) {
  max-height: 300px;
}
.accordion-panel[hidden] {
  display: block !important;
  max-height: 0;
  visibility: hidden;
}

.accordion-content {
  padding: 0 var(--space-6) var(--space-6) calc(36px + var(--space-6) + var(--space-4));
  color: var(--text-secondary);
  line-height: 1.75;
  font-size: .95rem;
}

.accordion-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  margin-top: var(--space-3);
  color: var(--red);
  font-weight: 600;
  font-size: .9rem;
  transition: gap var(--transition), opacity var(--transition);
}
.accordion-link:hover { gap: var(--space-2); opacity: .8; }

/* ── Get Involved ───────────────────────────────────────────── */
.get-involved {
  padding-block: var(--space-24);
  background: var(--navy);
}

.involved-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-6);
  margin-bottom: var(--space-6);
}
@media (min-width: 768px) {
  .involved-grid { grid-template-columns: repeat(3, 1fr); }
}

.involved-card {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  transition: background var(--transition), transform var(--transition);
}
.involved-card:hover {
  background: rgba(255,255,255,.1);
  transform: translateY(-4px);
}
.involved-card-featured {
  background: var(--red);
  border-color: var(--red-light);
  position: relative;
}
.involved-card-featured:hover {
  background: var(--red-dark);
}

.featured-badge {
  display: inline-block;
  background: rgba(255,255,255,.2);
  color: var(--white);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: 99px;
  margin-bottom: var(--space-3);
}

.involved-card-icon {
  width: 60px; height: 60px;
  background: rgba(255,255,255,.1);
  border-radius: var(--radius-lg);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: var(--space-5);
}

.involved-card h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: var(--space-3);
}
.involved-card p {
  color: rgba(255,255,255,.75);
  font-size: .92rem;
  line-height: 1.7;
  margin-bottom: var(--space-5);
}

.blood-drive-cta {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: var(--radius-xl);
  padding: var(--space-6) var(--space-8);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  flex-wrap: wrap;
}
.blood-drive-content {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  flex: 1;
}
.blood-drive-content div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.blood-drive-content strong {
  color: var(--white);
  font-size: 1rem;
}
.blood-drive-content span {
  color: rgba(255,255,255,.7);
  font-size: .88rem;
}

/* ── News Carousel ──────────────────────────────────────────── */
.news {
  padding-block: var(--space-24);
  background: var(--gray-50);
}

.news-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: var(--space-8);
  gap: var(--space-4);
  flex-wrap: wrap;
}
.news-header h2 {
  font-family: var(--font-heading);
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  font-weight: 900;
  color: var(--navy);
}

.carousel-controls {
  display: flex;
  gap: var(--space-2);
  flex-shrink: 0;
}
.carousel-btn {
  width: 44px; height: 44px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  color: var(--text-secondary);
  background: var(--white);
  transition: background var(--transition), border-color var(--transition),
              color var(--transition), box-shadow var(--transition);
}
.carousel-btn:hover {
  background: var(--navy);
  border-color: var(--navy);
  color: var(--white);
  box-shadow: var(--shadow-sm);
}

.carousel-viewport {
  overflow: hidden;
  border-radius: var(--radius-xl);
}

.carousel-track {
  display: flex;
  gap: var(--space-5);
  transition: transform var(--transition-slow) cubic-bezier(0.4, 0, 0.2, 1);
}

.news-card {
  flex: 0 0 calc(100% - 0px);
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
  transition: box-shadow var(--transition);
}
.news-card:hover { box-shadow: var(--shadow-md); }

@media (min-width: 768px) {
  .news-card { flex: 0 0 calc(50% - 10px); }
}
@media (min-width: 1024px) {
  .news-card { flex: 0 0 calc(33.333% - 14px); }
}

.news-card-image {
  position: relative;
  overflow: hidden;
}
.news-card-image img {
  width: 100%;
  height: 200px;
  object-fit: cover;
  transition: transform 400ms ease;
}
.news-card:hover .news-card-image img { transform: scale(1.04); }

.news-tag {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 99px;
}
.news-tag-urgent  { background: #fee2e2; color: #991b1b; }
.news-tag-ongoing { background: #fef3c7; color: #92400e; }
.news-tag-campaign{ background: #dbeafe; color: #1e40af; }
.news-tag-story   { background: #d1fae5; color: #065f46; }

.news-card-content { padding: var(--space-5) var(--space-6); }

.news-date {
  display: block;
  font-size: .78rem;
  color: var(--text-muted);
  margin-bottom: var(--space-2);
  font-weight: 500;
}

.news-card-content h3 {
  font-size: 1rem;
  font-weight: 700;
  color: var(--navy);
  line-height: 1.4;
  margin-bottom: var(--space-3);
}
.news-card-content h3 a { transition: color var(--transition); }
.news-card-content h3 a:hover { color: var(--red); }

.news-card-content p {
  font-size: .88rem;
  color: var(--text-secondary);
  line-height: 1.65;
  margin-bottom: var(--space-4);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.news-read-more {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  color: var(--red);
  font-size: .85rem;
  font-weight: 600;
  transition: gap var(--transition);
}
.news-read-more:hover { gap: var(--space-2); }

.carousel-indicators {
  display: flex;
  justify-content: center;
  gap: var(--space-2);
  margin-top: var(--space-6);
}
.carousel-dot {
  width: 8px; height: 8px;
  border-radius: 99px;
  background: var(--gray-300);
  transition: background var(--transition), width var(--transition);
  cursor: pointer;
}
.carousel-dot.active {
  background: var(--red);
  width: 24px;
}

/* ── Donate CTA ─────────────────────────────────────────────── */
.donate-cta {
  padding-block: var(--space-24);
  background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 60%, var(--navy-light) 100%);
  position: relative;
  overflow: hidden;
}
.donate-cta::before {
  content: '';
  position: absolute;
  top: -60px; right: -60px;
  width: 300px; height: 300px;
  border-radius: 50%;
  background: rgba(196,30,58,.12);
  pointer-events: none;
}
.donate-cta::after {
  content: '';
  position: absolute;
  bottom: -80px; left: -40px;
  width: 250px; height: 250px;
  border-radius: 50%;
  background: rgba(255,255,255,.04);
  pointer-events: none;
}

.donate-cta-inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-12);
  align-items: start;
  position: relative;
  z-index: 1;
}
@media (min-width: 900px) {
  .donate-cta-inner { grid-template-columns: 1fr 1fr; align-items: center; }
}

.donate-cta-content h2 {
  font-family: var(--font-heading);
  font-size: clamp(1.7rem, 3vw, 2.4rem);
  font-weight: 900;
  color: var(--white);
  line-height: 1.2;
  margin-bottom: var(--space-5);
}

.donate-desc {
  color: rgba(255,255,255,.8);
  line-height: 1.75;
  margin-bottom: var(--space-6);
}
.donate-desc strong { color: var(--white); }

.donate-trust-badges {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4);
}
.trust-badge {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  color: rgba(255,255,255,.7);
  font-size: .82rem;
  font-weight: 500;
}

.donate-cta-form {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  box-shadow: var(--shadow-xl);
}
.donate-cta-form h3 {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: var(--space-5);
  text-align: center;
}

.amount-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-3);
  margin-bottom: var(--space-5);
}

.amount-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: var(--space-4) var(--space-3);
  border: 2px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--white);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition), transform var(--transition);
  position: relative;
  text-align: center;
}
.amount-btn:hover {
  border-color: var(--red);
  background: var(--red-muted);
  transform: translateY(-2px);
}
.amount-btn.selected {
  border-color: var(--red);
  background: var(--red-muted);
}
.amount-btn-popular {
  border-color: var(--red);
  background: var(--red-muted);
}

.popular-label {
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--red);
  color: var(--white);
  font-size: .65rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 99px;
  white-space: nowrap;
}

.amount-value {
  font-family: var(--font-heading);
  font-size: 1.4rem;
  font-weight: 900;
  color: var(--navy);
  line-height: 1.2;
}
.amount-impact {
  font-size: .75rem;
  color: var(--text-muted);
  margin-top: 2px;
}

/* ── Donate Modal ───────────────────────────────────────────── */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.6);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-4);
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition-slow);
  backdrop-filter: blur(4px);
}
.modal-overlay.open {
  opacity: 1;
  pointer-events: all;
}

.modal-container {
  background: var(--white);
  border-radius: var(--radius-xl);
  width: 100%;
  max-width: 540px;
  max-height: 90dvh;
  overflow-y: auto;
  position: relative;
  box-shadow: var(--shadow-xl);
  transform: scale(0.95) translateY(10px);
  transition: transform var(--transition-slow);
}
.modal-overlay.open .modal-container {
  transform: scale(1) translateY(0);
}

.modal-close {
  position: absolute;
  top: var(--space-4);
  right: var(--space-4);
  width: 44px; height: 44px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-md);
  color: var(--text-muted);
  transition: background var(--transition), color var(--transition);
  z-index: 1;
}
.modal-close:hover { background: var(--gray-100); color: var(--text-primary); }

.modal-header {
  background: linear-gradient(135deg, var(--navy-dark), var(--navy));
  padding: var(--space-8) var(--space-8) var(--space-6);
  text-align: center;
  border-radius: var(--radius-xl) var(--radius-xl) 0 0;
}
.modal-logo {
  margin: 0 auto var(--space-3);
  width: fit-content;
}
.modal-header h2 {
  font-family: var(--font-heading);
  font-size: 1.4rem;
  font-weight: 900;
  color: var(--white);
  margin-bottom: var(--space-2);
}
.modal-header p {
  color: rgba(255,255,255,.75);
  font-size: .9rem;
}

.modal-form {
  padding: var(--space-6) var(--space-8) var(--space-8);
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
}

.form-legend {
  font-size: .82rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: var(--space-3);
  display: block;
}

fieldset { border: none; }

.modal-amounts {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-3);
}

.modal-amount-label { cursor: pointer; }
.modal-amount-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: var(--space-4) var(--space-3);
  border: 2px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--white);
  transition: border-color var(--transition), background var(--transition);
  position: relative;
  text-align: center;
}
input[type="radio"]:checked + .modal-amount-btn,
.modal-amount-btn-selected {
  border-color: var(--red) !important;
  background: var(--red-muted) !important;
}
.modal-amount-label:hover .modal-amount-btn {
  border-color: var(--red);
  background: var(--red-muted);
}
.modal-popular-tag {
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--red);
  color: var(--white);
  font-size: .65rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 99px;
  white-space: nowrap;
}
.modal-amount-value {
  font-family: var(--font-heading);
  font-size: 1.3rem;
  font-weight: 900;
  color: var(--navy);
  line-height: 1.2;
}
.modal-amount-impact {
  font-size: .72rem;
  color: var(--text-muted);
  margin-top: 2px;
}

.custom-amount-row {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  margin-top: var(--space-3);
}
.custom-amount-label {
  font-size: .88rem;
  font-weight: 500;
  color: var(--text-secondary);
}
.custom-amount-input-wrap {
  position: relative;
}
.currency-prefix {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  font-weight: 600;
  color: var(--text-secondary);
  pointer-events: none;
}
.custom-amount-input {
  width: 100%;
  padding: 10px 12px 10px 28px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  font-family: var(--font-body);
  font-size: .95rem;
  color: var(--text-primary);
  background: var(--white);
  transition: border-color var(--transition), box-shadow var(--transition);
}
.custom-amount-input:focus {
  border-color: var(--red);
  outline: none;
  box-shadow: 0 0 0 3px rgba(196,30,58,.15);
}
.form-hint {
  font-size: .78rem;
  color: var(--text-muted);
}

.freq-row {
  display: flex;
  gap: var(--space-3);
}
.freq-label {
  flex: 1;
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: 10px var(--space-4);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  font-size: .9rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
}
.freq-label:has(input:checked) {
  border-color: var(--navy);
  background: rgba(27,58,92,.06);
  color: var(--navy);
}
.freq-label input { accent-color: var(--navy); }

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-4);
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}
.form-label {
  font-size: .88rem;
  font-weight: 600;
  color: var(--text-secondary);
}
.required { color: var(--red); }
.form-input {
  padding: 10px 12px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  font-family: var(--font-body);
  font-size: .95rem;
  color: var(--text-primary);
  background: var(--white);
  transition: border-color var(--transition), box-shadow var(--transition);
  min-height: 44px;
}
.form-input:focus {
  border-color: var(--red);
  outline: none;
  box-shadow: 0 0 0 3px rgba(196,30,58,.15);
}

.modal-actions {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}
.modal-security {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  font-size: .78rem;
  color: var(--text-muted);
  text-align: center;
}

/* ── Footer ─────────────────────────────────────────────────── */
.site-footer {
  background: var(--gray-900);
  color: rgba(255,255,255,.7);
}

.footer-top {
  padding: var(--space-16) 0 var(--space-12);
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-12);
}
@media (min-width: 900px) {
  .footer-top { grid-template-columns: 280px 1fr; }
}

.footer-brand .logo-name { color: var(--white); }
.footer-brand .logo-tagline { color: rgba(255,255,255,.5); }

.footer-desc {
  font-size: .9rem;
  line-height: 1.7;
  color: rgba(255,255,255,.6);
  margin-top: var(--space-4);
  margin-bottom: var(--space-5);
}

.footer-social {
  display: flex;
  gap: var(--space-3);
}
.footer-social a {
  width: 38px; height: 38px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,.6);
  transition: background var(--transition), color var(--transition), border-color var(--transition);
}
.footer-social a:hover {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.footer-nav {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-8);
}
@media (min-width: 600px) {
  .footer-nav { grid-template-columns: repeat(4, 1fr); }
}

.footer-nav-col h4 {
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--white);
  margin-bottom: var(--space-4);
}
.footer-nav-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}
.footer-nav-col a {
  font-size: .88rem;
  color: rgba(255,255,255,.55);
  transition: color var(--transition);
  line-height: 1.4;
}
.footer-nav-col a:hover { color: var(--white); }

.footer-bottom {
  padding-block: var(--space-5);
  border-top: 1px solid rgba(255,255,255,.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  flex-wrap: wrap;
  font-size: .82rem;
  color: rgba(255,255,255,.4);
}
.footer-bottom-links {
  display: flex;
  gap: var(--space-4);
}
.footer-bottom-links a {
  color: rgba(255,255,255,.4);
  transition: color var(--transition);
}
.footer-bottom-links a:hover { color: rgba(255,255,255,.7); }

/* ── Responsive Adjustments ─────────────────────────────────── */
@media (max-width: 767px) {
  .main-nav { display: none; }
  .hamburger { display: flex; }

  .hero-actions .btn { width: 100%; justify-content: center; }
  .hero-actions { flex-direction: column; }

  .stats-grid { grid-template-columns: repeat(2,1fr); gap: var(--space-4); }

  .mission-image img { height: 260px; }

  .accordion-content { padding-left: var(--space-6); }

  .donate-cta-inner { gap: var(--space-8); }

  .form-row { grid-template-columns: 1fr; }

  .modal-form { padding: var(--space-5) var(--space-5) var(--space-6); }
  .modal-header { padding: var(--space-6) var(--space-5) var(--space-5); }
}

@media (max-width: 480px) {
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .stat-card { padding: var(--space-5) var(--space-4); }
  .blood-drive-cta { flex-direction: column; align-items: flex-start; }
  .utility-links { display: none; }
}

/* ── Animations ─────────────────────────────────────────────── */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes countUp {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.stat-card { animation: fadeInUp 0.4s ease both; }
.stat-card:nth-child(1) { animation-delay: 0.05s; }
.stat-card:nth-child(2) { animation-delay: 0.12s; }
.stat-card:nth-child(3) { animation-delay: 0.19s; }
.stat-card:nth-child(4) { animation-delay: 0.26s; }

